package notification.core.artifact;import lombok.Getter;import notification.core.artifact.Artifact;@Getterpublic final class TemplateContext implements Artifact {    private static final String DEFAULT_VERSION = "v1";    private final String version;    public TemplateContext(String version) {        if (version == null || version.isBlank()) {            throw new IllegalArgumentException(                    "Template version cannot be null or empty"            );        }        this.version = version;    }    /**     * Creates the default template context.     */    public static TemplateContext defaultContext() {        return new TemplateContext(DEFAULT_VERSION);    }}